(globalThis.CATALOGUE_RECORD_CHUNKS??=Object.create(null))[394]={"source_order":394,"notes":["Whether the faint ghost writing is show-through from the reverse side or offset from a facing page cannot be determined. None of it is legible enough to read.","The folio number is read as '197' with a superscript 'b'. The final letter could also be read as 'b' or as 'v'-like, but 'b' matches the supplied folio label.","The page is the verso following fol. 197. The adjacent fol. 197 and fol. 198 pages carry dense catalogue entries, but none of that text is on this target page.","Faint show-through or offset patterns appear across the ruled lines. They are treated as bleed-through, not as target-page entries.","Image review of the overview and all six native tiles found only ruled lines and no legible target-page writing other than the folio number '197b'. This covers the top, middle, bottom, gutter (left) and outer (right) margins and the interlinear spaces.","Very faint ghost writing is visible across many ruled lines, most noticeably in the middle and lower areas. It is illegible and is treated as show-through or offset, not as target-page text. It is not transcribed.","Non-text marks include: a small dark blot or tab-like mark near the left edge at about [335,550,45,95]; speckled foxing or smudging in the left margin at about [340,1690,360,150]; and a faint diagonal stray pencil or scratch stroke at about [400,1960,250,140], which does not read as an arrow attached to any entry. Scattered specks also occur across the page.","Binding thread is visible along the right edge.","The dense catalogue entries on the adjacent pages, fol. 197 and fol. 198, do not appear on this page and are not transcribed here.","Very faint ghost patterns resembling handwriting lie across many ruled lines, most visibly in the middle and lower areas. They are not legible. They could be show-through from the reverse of the leaf or offset from a facing page. They were not transcribed, and the review did not establish their source."],"records":[{"id":"css-prod-0394-r001","local_id":"r001","source_order":394,"folio":"197b","folio_label":"fol. 197b","sequence":1,"page_id":"b1fd5aab-dee7-4761-bc43-c19e849da716","kind":"other","record_type":"non_catalogue_text","source_model_record_type":"non_catalogue_text","subtype":"folio_number","shelfmark":"","titleLiteral":"","titleNormalized":"","displayTitle":"Catalogue text","authorOrSource":"","source":"","subject":"","subjectGroup":"","date":"","extent":"","lines":"","script":"","incipit":"","transcription":"197ᵇ","annotations":["Handwritten folio number in the top left corner, apparently in pencil. The 'b' is written superscript after '197'.","No catalogue entry is attached to this number."],"uncertainties":["The superscript letter is read as 'b'. It is a small, rounded form, and 'b' agrees with the supplied folio label.","Very faint ghost patterns resembling handwriting lie across many ruled lines, most visibly in the middle and lower areas. They are not legible. They could be show-through from the reverse of the leaf or offset from a facing page. They were not transcribed, and the review did not establish their source."],"focused_readings":[],"reviewNotes":[],"editorialNotes":[],"relationships":[],"editorial_context":[],"block_ids":["b001"],"locations":[{"block_id":"b001","bbox":[405,310,135,110]}],"isCancelled":false,"needsReview":true,"human_verified":false,"verification_status":"machine_reviewed","change_audit":[],"sourceCitationURL":"https://iiif.bodleian.ox.ac.uk/iiif/canvas/b1fd5aab-dee7-4761-bc43-c19e849da716.json","auditPath":"audit/pages/0394.json","attachedNotes":[],"resolvedRelationships":[],"attachedRecords":[]}]};
